  /**
   * Converts raw service attribute pairs into a map, rewriting deprecated duplicate keys used by data node services.
   */
  public static Map<String, Object> convertServicePairsToMap(List<NonnullPair<String, Object>> pairs)
  {
    if (pairs == null || pairs.isEmpty()) {
      return Maps.newHashMapWithExpectedSize(0);
    }
    final Map<String, Object> map = Maps.newHashMapWithExpectedSize(pairs.size());
    for (NonnullPair<String, Object> pair : pairs) {
      final Object prevVal = map.put(pair.lhs, pair.rhs);
      if (prevVal != null) {
        if ("type".equals(pair.lhs)) {
          if (DataNodeService.DISCOVERY_SERVICE_KEY.equals(prevVal)) {
            map.put("type", prevVal);
            map.put(DataNodeService.SERVER_TYPE_PROP_KEY, pair.rhs);
            continue;
          } else if (DataNodeService.DISCOVERY_SERVICE_KEY.equals(pair.rhs)) {
            map.put(DataNodeService.SERVER_TYPE_PROP_KEY, prevVal);
            continue;
          }
        } else if (DataNodeService.SERVER_TYPE_PROP_KEY.equals(pair.lhs)) {
          continue;
        }

        if (!prevVal.equals(pair.rhs)) {
          throw new IAE("Duplicate key[%s] with different values: [%s] and [%s]", pair.lhs, prevVal, pair.rhs);
        }
      }
    }
    return map;
  }

  @Nullable
  public static <T extends DruidService> T lookupTypedService(
      Map<String, DruidService> services,
      String key,
      Class<T> clazz
  )
  {
    if (services == null || key == null || clazz == null) {
      return null;
    }
    Map<String, DruidService> discoverable = filterDiscoverableServices(services);
    final DruidService o = discoverable.get(key);
    if (o == null) {
      final DruidService raw = services.get(key);
      if (raw != null && clazz.isAssignableFrom(raw.getClass())) {
        //noinspection unchecked
        return (T) raw;
      }
      return null;
    }
    if (clazz.isAssignableFrom(o.getClass())) {
      //noinspection unchecked
      return (T) o;
    }
    return null;
  }

