  public static void copyRequestHeaders(Request source, Request target)
  {
    if (source == null || target == null) {
      return;
    }
    Multimap<String, String> headers = source.getHeaders();
    if (headers != null && !headers.isEmpty()) {
      target.addHeaderValues(headers);
    }
  }

  public static void copyRequestContent(Request source, Request target)
  {
    if (source == null || target == null) {
      return;
    }
    if (source.hasContent()) {
      ChannelBuffer content = source.getContent();
      if (content != null) {
        target.setContent(content);
      }
    }
  }

