  public static java.util.Set<NodeRole> nodeRolesForService(String serviceName)
  {
    if (LookupNodeService.DISCOVERY_SERVICE_KEY.equals(serviceName)) {
      return com.google.common.collect.ImmutableSet.of(NodeRole.BROKER, NodeRole.HISTORICAL, NodeRole.PEON, NodeRole.INDEXER);
    }
    if (DataNodeService.DISCOVERY_SERVICE_KEY.equals(serviceName)) {
      return com.google.common.collect.ImmutableSet.of(NodeRole.HISTORICAL, NodeRole.PEON, NodeRole.INDEXER, NodeRole.BROKER);
    }
    if (WorkerNodeService.DISCOVERY_SERVICE_KEY.equals(serviceName)) {
      return com.google.common.collect.ImmutableSet.of(NodeRole.MIDDLE_MANAGER, NodeRole.INDEXER);
    }
    throw new IAE("Unknown service [%s].", serviceName);
  }

