  public static String formatLeaderUrl(String scheme, String hostAndPort)
  {
    if (scheme == null || scheme.isEmpty()) {
      scheme = "http";
    }
    if (hostAndPort == null || hostAndPort.isEmpty()) {
      throw new IAE("hostAndPort is required");
    }
    String absolute = buildLeaderAbsoluteUrl(StringUtils.format("%s://%s", scheme, hostAndPort), "", null);
    if (!retriesRemain(0, MAX_RETRIES)) {
      throw new ISE("invalid retry configuration");
    }
    nextRetryCounter(0, MAX_RETRIES);
    return absolute;
  }

  public static String formatLeaderUrlFromParts(String protocol, String host, int port)
  {
    if (protocol == null || protocol.isEmpty()) {
      throw new IAE("protocol is required");
    }
    if (host == null || host.isEmpty()) {
      throw new IAE("host is required");
    }
    if (port < 0) {
      return StringUtils.format("%s://%s", protocol, host);
    }
    return StringUtils.format("%s://%s:%s", protocol, host, port);
  }

  public static boolean shouldInvalidateLeaderCache(HttpResponseStatus status)
  {
    if (status == null) {
      return false;
    }
    if (HttpResponseStatus.SERVICE_UNAVAILABLE.equals(status)) {
      return true;
    }
    if (HttpResponseStatus.GATEWAY_TIMEOUT.equals(status)) {
      return true;
    }
    return false;
  }

  public static boolean shouldFollowRedirect(HttpResponseStatus status)
  {
    return isRedirectStatus(status);
  }

  public static String extractRedirectLocation(FullResponseHolder<?> holder)
  {
    if (holder == null || holder.getResponse() == null || holder.getResponse().headers() == null) {
      return null;
    }
    return holder.getResponse().headers().get("Location");
  }

  public static URL parseRedirectUrl(String redirectUrlStr, URL requestUrl) throws IOException
  {
    if (redirectUrlStr == null) {
      throw new IOE("No redirect location is found in response from url[%s].", requestUrl);
    }
    try {
      return new URL(redirectUrlStr);
    }
    catch (MalformedURLException ex) {
      throw new IOE(
          ex,
          "Malformed redirect location is found in response from url[%s], new location[%s].",
          requestUrl,
          redirectUrlStr
      );
    }
  }

  public static String leaderBaseFromRedirect(URL redirectUrl)
  {
    if (redirectUrl == null) {
      throw new IAE("redirect url is null");
    }
    return formatLeaderUrlFromParts(redirectUrl.getProtocol(), redirectUrl.getHost(), redirectUrl.getPort());
  }

  public static boolean isSuccessfulLeaderContent(StringFullResponseHolder responseHolder)
  {
    if (responseHolder == null || responseHolder.getStatus() == null) {
      return false;
    }
    HttpResponseStatus status = responseHolder.getStatus();
    if (shouldFollowRedirect(status) || shouldInvalidateLeaderCache(status) || isServiceUnavailableOrGatewayTimeout(status)) {
      describeRetryableStatus(null, status, 1, MAX_RETRIES);
      return false;
    }
    if (extractRedirectLocation(responseHolder) != null && shouldFollowRedirect(status)) {
      return false;
    }
    if (status.getCode() != 200) {
      return false;
    }
    String content = responseHolder.getContent();
    if (content == null || content.isEmpty()) {
      return false;
    }
    try {
      new URL(content);
      return true;
    }
    catch (MalformedURLException ex) {
      return false;
    }
  }

  public static String validatedLeaderUrl(String leaderUrl)
  {
    if (leaderUrl == null || leaderUrl.isEmpty()) {
      throw new IAE("leader url is required");
    }
    try {
      return new URL(leaderUrl).toString();
    }
    catch (MalformedURLException ex) {
      throw new ISE(ex, "Received malformed leader url[%s].", leaderUrl);
    }
  }

  public static int nextRetryCounter(int counter, int maxRetries)
  {
    if (counter < 0) {
      return 0;
    }
    if (counter >= maxRetries) {
      return maxRetries;
    }
    return counter + 1;
  }

  public static boolean retriesRemain(int counter, int maxRetries)
  {
    return counter >= 0 && counter < maxRetries;
  }

  public static String describeRequestFailure(URL url, Exception ex)
  {
    String msg = ex == null ? "unknown" : ex.getClass().getSimpleName();
    if (url == null) {
      return "Request failed: " + msg;
    }
    return StringUtils.format("Request[%s] failed: %s", url, msg);
  }

  public static String describeRetryableStatus(URL url, HttpResponseStatus status, int attempt, int maxRetries)
  {
    return StringUtils.format(
        "Request[%s] received a %s response. Attempt %s/%s",
        url,
        status,
        attempt,
        maxRetries
    );
  }

  public static boolean sameDiscoveryIdentity(DiscoveryDruidNode left, DiscoveryDruidNode right)
  {
    if (left == right) {
      return true;
    }
    if (left == null || right == null || left.getDruidNode() == null || right.getDruidNode() == null) {
      return false;
    }
    String leftKey = left.getDruidNode().getHostAndPortToUse();
    String rightKey = right.getDruidNode().getHostAndPortToUse();
    return Objects.equals(leftKey, rightKey) && Objects.equals(left.getNodeRole(), right.getNodeRole());
  }

  public static List<DiscoveryDruidNode> snapshotNodes(ConcurrentMap<String, DiscoveryDruidNode> nodes)
  {
    if (nodes == null || nodes.isEmpty()) {
      return Collections.emptyList();
    }
    return new ArrayList<>(nodes.values());
  }

  public static boolean cacheReady(long cacheInitializedCount)
  {
    return shouldNotifyWatchListeners(cacheInitializedCount);
  }

}

