+          // The leader may have moved (for example during a rolling restart) or an intermediary proxy may be
+          // returning an error. Clear the cache so that the next attempt re-resolves the leader, then retry.
+          log.warn(
+              "Request[%s] received a %s response. Clearing leader cache and retrying.",
+              request.getUrl(),
+              responseStatus
+          );
+
+          try {
+            if (request.getUrl().getQuery() == null) {
+              request = withUrl(
